style.css:
@-moz-document domain("allen.in") {
/* General Body Cleanup */
  body {
    background-color: #f4f7fa !important;
    font-family: 'Segoe UI', 'Helvetica Neue', sans-serif !important;
    color: #333 !important;
  }

  /* Header Customization */
  header, .top-nav, .navbar {
    background-color: #004a99 !important;
    color: #fff !important;
    border-bottom: 3px solid #0066cc !important;
  }

  header a, .navbar a {
    color: #ffffff !important;
    font-weight: 500 !important;
  }

  /* Hero Section */
  .hero-banner {
    background: linear-gradient(to right, #0056b3, #0073e6) !important;
    color: #fff !important;
    text-align: center !important;
    padding: 60px 20px !important;
  }

  .hero-banner h1 {
    font-size: 2.5rem !important;
    font-weight: 700 !important;
  }

  .hero-banner p {
    font-size: 1.2rem !important;
    margin-top: 10px !important;
  }

  /* Course Cards */
  .course-card {
    background-color: #ffffff !important;
    border: 1px solid #e0e0e0 !important;
    border-radius: 8px !important;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1) !important;
    overflow: hidden !important;
    transition: transform 0.3s ease !important;
  }

  .course-card:hover {
    transform: translateY(-5px) !important;
  }

  .course-card img {
    width: 100% !important;
    height: auto !important;
  }

  .course-card .card-body {
    padding: 20px !important;
  }

  .course-card h5 {
    font-size: 1.2rem !important;
    font-weight: 600 !important;
  }

  .course-card p {
    font-size: 1rem !important;
    color: #555 !important;
  }

  /* Footer */
  footer {
    background-color: #003366 !important;
    color: #fff !important;
    padding: 40px 20px !important;
    text-align: center !important;
  }

  footer a {
    color: #ffffff !important;
    text-decoration: none !important;
    font-weight: 500 !important;
  }

  footer a:hover {
    text-decoration: underline !important;
  }

  /* Buttons */
  .btn-primary {
    background-color: #0073e6 !important;
    border-color: #005bb5 !important;
  }

  .btn-primary:hover {
    background-color: #005bb5 !important;
    border-color: #004a99 !important;
  }

  /* Input Fields */
  input, select, textarea {
    border-radius: 8px !important;
    border: 1px solid #ccc !important;
    padding: 10px !important;
    font-size: 1rem !important;
    width: 100% !important;
  }

  input:focus, select:focus, textarea:focus {
    border-color: #0073e6 !important;
    box-shadow: 0 0 5px rgba(0, 115, 230, 0.5) !important;
  }
}
